-- DADOS 100% FICTICIOS, SOMENTE PARA FINS DIDATICOS.
-- PostgreSQL | jan/2019 a nov/2026 (novembro completo e SIMULADO).
-- Esta base propositalmente contem CNPJs/NIREs repetidos para exercicios de qualidade.
-- IMPORTANTE: ao executar, a tabela public.empresas_sc anterior sera recriada.
-- Nao ha campo situacao_cadastral; ele deve ser calculado pelos alunos.
-- Uma unica tabela de dados; sem views, tabelas agregadas ou gabaritos.
DROP TABLE IF EXISTS public.empresas_sc;
CREATE TABLE public.empresas_sc (
    id_registro                  BIGINT PRIMARY KEY,
    nome_fantasia                VARCHAR(180) NOT NULL,
    razao_social                 VARCHAR(220) NOT NULL,
    nire                         VARCHAR(20) NOT NULL,
    cnpj                         VARCHAR(18) NOT NULL,
    data_abertura                DATE NOT NULL,
    data_extincao                DATE NULL,
    logradouro                   VARCHAR(180),
    numero                       VARCHAR(15),
    complemento                  VARCHAR(140),
    bairro                       VARCHAR(130),
    cep                          VARCHAR(10),
    municipio                    VARCHAR(130) NOT NULL,
    uf                           CHAR(2) NOT NULL DEFAULT 'SC',
    cnae_principal               VARCHAR(12),
    atividade_principal          TEXT,
    codigo_natureza_juridica     VARCHAR(10),
    natureza_juridica            VARCHAR(160),
    porte                        VARCHAR(100),
    estabelecimento_online       VARCHAR(3),
    tipo_estabelecimento         VARCHAR(15),
    capital_social_brl           NUMERIC(15,2),
    qtd_empregados               INTEGER,
    canal_registro               VARCHAR(100),
    origem_registro              VARCHAR(120),
    CONSTRAINT ck_datas_empresa CHECK (data_extincao IS NULL OR data_extincao >= data_abertura),
    CONSTRAINT ck_uf_sc CHECK (uf = 'SC')
);































-- Indices auxiliares de desempenho (nao sao tabelas/abas extras).
CREATE INDEX idx_empresas_sc_cnpj ON public.empresas_sc (cnpj);
CREATE INDEX idx_empresas_sc_abertura ON public.empresas_sc (data_abertura);
CREATE INDEX idx_empresas_sc_extincao ON public.empresas_sc (data_extincao);
CREATE INDEX idx_empresas_sc_municipio ON public.empresas_sc (municipio);
CREATE INDEX idx_empresas_sc_atividade ON public.empresas_sc (cnae_principal);
